import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.75.0";
import { corsHeaders } from "../_shared/cors.ts";
import {
  dbFromSchema,
  MASTER_TABLES,
  resolveEmpresaDb,
} from "../_shared/empresa-tables.ts";
import { ensurePontuaGarboPartnerLead } from "../_shared/pontua-garbo-lead.ts";

async function upsertUsuario(
  admin: ReturnType<typeof createClient>,
  target: ReturnType<typeof resolveEmpresaDb>,
  userId: string,
  nome: string,
  email: string,
  telefone: string | undefined,
  tipo_usuario: string = "colaborador",
  titulo: string | undefined = undefined,
  comissao_ativa: boolean = false,
) {
  const db = dbFromSchema(admin, target.schema);

  const { data: usuarioExistente, error: checkError } = await db
    .from(target.usuariosTable)
    .select("id")
    .eq("id", userId)
    .maybeSingle();

  if (checkError && checkError.code !== "PGRST116") {
    throw checkError;
  }

  if (usuarioExistente) {
    const { error: updateUsuariosError } = await db
      .from(target.usuariosTable)
      .update({
        status_convite: "ATIVO",
        nome,
        telefone,
        tipo_usuario,
        titulo: titulo ?? null,
        comissao_ativa,
      })
      .eq("id", userId);

    if (updateUsuariosError) throw updateUsuariosError;
  } else {
    const { error: insertUsuariosError } = await db
      .from(target.usuariosTable)
      .insert({
        id: userId,
        nome,
        email,
        telefone,
        status_convite: "ATIVO",
        tipo_usuario,
        titulo: titulo ?? null,
        comissao_ativa,
      });

    if (insertUsuariosError) throw insertUsuariosError;
  }
}

async function syncRoles(
  admin: ReturnType<typeof createClient>,
  target: ReturnType<typeof resolveEmpresaDb>,
  userId: string,
  rolesInput: string[] | string | undefined,
) {
  const db = dbFromSchema(admin, target.schema);
  const raw = Array.isArray(rolesInput)
    ? rolesInput
    : rolesInput
      ? [rolesInput]
      : ["nenhum"];

  const allowed = new Set(["admin", "vendedor", "marketing", "nenhum"]);
  const unique = Array.from(
    new Set(
      raw
        .map((r) => String(r || "").toLowerCase())
        .filter((r) => allowed.has(r)),
    ),
  );

  const operational = unique.filter((r) => r !== "nenhum");
  const roles = operational.length > 0 ? operational : ["nenhum"];

  const { error: deleteError } = await db
    .from(target.rolesTable)
    .delete()
    .eq("user_id", userId);

  if (deleteError) throw deleteError;

  const { error: insertError } = await db
    .from(target.rolesTable)
    .insert(roles.map((role) => ({ user_id: userId, role })));

  if (insertError) throw insertError;
}

async function linkUsuarioEmpresa(
  admin: ReturnType<typeof createClient>,
  userId: string,
  empresaId: string,
) {
  const { error } = await admin
    .from(MASTER_TABLES.usuario_empresa)
    .upsert(
      { user_id: userId, empresa_id: empresaId },
      { onConflict: "user_id,empresa_id" },
    );

  if (error) throw error;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseClient = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    );

    const { nome, email, telefone, role, roles, empresaId, schemaNome, tipo_usuario, titulo, comissao_ativa, leadId } =
      await req.json();

    if (!empresaId || !schemaNome) {
      throw new Error(
        "empresaId e schemaNome são obrigatórios. Selecione a empresa antes de cadastrar o usuário.",
      );
    }

    const target = resolveEmpresaDb(schemaNome);

    console.log("Processing user request:", { nome, email, role, roles, tipo_usuario, empresaId, schemaNome });

    const { data: existingUserData, error: listUsersError } =
      await supabaseClient.auth.admin.listUsers({
        page: 1,
        perPage: 1000,
      });

    if (listUsersError) throw listUsersError;

    const existingUser =
      existingUserData?.users?.find(
        (u: { email?: string }) => u.email?.toLowerCase() === email.toLowerCase(),
      ) ?? null;

    let userId: string;
    let message: string;

    if (existingUser) {
      const { error: updateAuthError } = await supabaseClient.auth.admin.updateUserById(
        existingUser.id,
        {
          email_confirm: true,
          user_metadata: {
            name: nome,
            phone: telefone,
          },
        },
      );

      if (updateAuthError) throw updateAuthError;

      userId = existingUser.id;
      message = "Usuário reativado e vinculado à empresa com sucesso";
    } else {
      // Senha temporária interna: evita e-mail automático de convite do Auth.
      // O admin define a senha real em Admin → Redefinir senha.
      const tempPassword = crypto.randomUUID() + "Aa1!";
      const { data: authData, error: authError } = await supabaseClient.auth.admin.createUser({
        email,
        password: tempPassword,
        email_confirm: true,
        user_metadata: {
          name: nome,
          phone: telefone,
        },
      });

      if (authError) throw authError;
      if (!authData.user) throw new Error("Falha ao criar usuário");

      userId = authData.user.id;
      message = "Usuário criado e vinculado à empresa com sucesso";
    }

    await upsertUsuario(
      supabaseClient,
      target,
      userId,
      nome,
      email,
      telefone,
      tipo_usuario ?? "colaborador",
      titulo,
      comissao_ativa ?? false,
    );
    await syncRoles(supabaseClient, target, userId, roles ?? role ?? "nenhum");
    await linkUsuarioEmpresa(supabaseClient, userId, empresaId);

    const entraPontuaGarbo = (comissao_ativa ?? false) === true;
    let pontuaGarboLeadId: number | null = null;
    if (entraPontuaGarbo) {
      try {
        const existingLeadId =
          typeof leadId === "number" && Number.isFinite(leadId) ? leadId : null;
        const ensured = await ensurePontuaGarboPartnerLead(supabaseClient, target, {
          usuarioId: userId,
          nome,
          email,
          telefone,
          existingLeadId,
        });
        pontuaGarboLeadId = ensured.leadId;
      } catch (leadErr) {
        console.error("create-user-admin: falha ao criar lead Pontua Garbo", leadErr);
      }
    }

    console.log("Operation completed successfully:", { userId, empresaId, schemaNome, tipo_usuario });

    return new Response(
      JSON.stringify({
        success: true,
        userId,
        message,
        leadId: pontuaGarboLeadId,
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
        status: 200,
      },
    );
  } catch (error: unknown) {
    const errMessage = error instanceof Error ? error.message : String(error);
    console.error("Error in create-user-admin:", error);
    return new Response(
      JSON.stringify({
        success: false,
        error: errMessage,
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
        status: 200,
      },
    );
  }
});

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, accept',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.75.0';

export const MASTER_TABLES = {
  usuarios: 'CRM-multi-empresas>usuarios<',
  user_roles: 'CRM-multi-empresas>user_roles<',
  usuario_empresa: 'CRM-multi-empresas>usuario_empresa<',
  leads: 'CRM-multi-empresas>leads<',
} as const;

export interface EmpresaDbTarget {
  schema: string | null;
  usuariosTable: string;
  rolesTable: string;
  leadsTable: string;
}

export function resolveEmpresaDb(schemaNome?: string | null): EmpresaDbTarget {
  if (schemaNome) {
    return {
      schema: schemaNome,
      usuariosTable: 'usuarios',
      rolesTable: 'user_roles',
      leadsTable: 'leads',
    };
  }
  return {
    schema: null,
    usuariosTable: MASTER_TABLES.usuarios,
    rolesTable: MASTER_TABLES.user_roles,
    leadsTable: MASTER_TABLES.leads,
  };
}

export function dbFromSchema(client: SupabaseClient, schema: string | null) {
  return schema ? client.schema(schema) : client;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.75.0";
import type { EmpresaDbTarget } from "./empresa-tables.ts";
import { dbFromSchema } from "./empresa-tables.ts";

export const PONTUA_GARBO_LEAD_ORIGEM = "Pontua Garbo";
const MIN_SCORE_VINCULO = 70;
const STOPWORDS = new Set([
  "de",
  "da",
  "do",
  "dos",
  "das",
  "e",
  "arquiteto",
  "arquiteta",
  "arquitetura",
  "arquitetos",
  "estudio",
  "studio",
  "consultor",
  "prestador",
]);

function digitsOnly(value: string | null | undefined): string {
  return (value ?? "").replace(/\D/g, "");
}

function todaySaoPaulo(): string {
  return new Date().toLocaleDateString("en-CA", { timeZone: "America/Sao_Paulo" });
}

function normalizePartnerName(value: string | null | undefined): string {
  return (value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function partnerNameTokens(value: string | null | undefined): string[] {
  return normalizePartnerName(value)
    .split(" ")
    .filter((token) => token.length >= 3 && !STOPWORDS.has(token));
}

function tokenInList(token: string, list: string[]): boolean {
  return list.some((item) => item === token || item.startsWith(token) || token.startsWith(item));
}

interface PartnerLeadRow {
  id: number;
  nome: string;
  email?: string | null;
  telefone?: string | null;
  status?: string | null;
  pontua_garbo_usuario_id?: string | null;
}

function scorePartnerLeadMatch(
  user: { usuarioId?: string; nome: string; email?: string | null; telefone?: string | null },
  lead: PartnerLeadRow,
): number {
  const userTokens = partnerNameTokens(user.nome);
  const leadTokens = partnerNameTokens(lead.nome);
  if (userTokens.length === 0 || leadTokens.length === 0) return 0;

  const userNorm = normalizePartnerName(user.nome);
  const leadNorm = normalizePartnerName(lead.nome);
  const startsWithUser =
    leadNorm.startsWith(userNorm) ||
    (userTokens.length >= 2 && leadTokens[0] === userTokens[0] && leadTokens[1] === userTokens[1]);
  const firstMatches = leadTokens[0] === userTokens[0];
  const remainingUser = userTokens.slice(1);
  const remainingMatched = remainingUser.filter((token) => tokenInList(token, leadTokens));

  let score = 0;
  if (startsWithUser) score = 90;
  else if (firstMatches && remainingUser.length === 0) score = leadTokens.length <= 2 ? 75 : 20;
  else if (firstMatches && remainingMatched.length >= 1 && leadTokens.length <= userTokens.length + 2) score = 80;
  else if (firstMatches && remainingMatched.length >= 1) score = 40;

  if (userTokens.length === 1 && leadTokens.length > 2) score = Math.min(score, 20);

  const userEmail = (user.email ?? "").trim().toLowerCase();
  const leadEmail = (lead.email ?? "").trim().toLowerCase();
  if (userEmail && leadEmail && userEmail === leadEmail) score = Math.max(score, 85);

  const status = (lead.status ?? "").toLowerCase();
  const nomeBruto = (lead.nome ?? "").toLowerCase();
  if (status.includes("arquitet") || nomeBruto.includes("arquitet")) score += 6;

  return Math.min(100, score);
}

function pickBestPartnerLead(
  user: { usuarioId?: string; nome: string; email?: string | null; telefone?: string | null },
  candidates: PartnerLeadRow[],
): PartnerLeadRow | null {
  let best: PartnerLeadRow | null = null;
  let bestScore = 0;
  for (const candidate of candidates) {
    const linkedToOther =
      Boolean(candidate.pontua_garbo_usuario_id) &&
      candidate.pontua_garbo_usuario_id !== user.usuarioId;
    if (linkedToOther) continue;
    const score = scorePartnerLeadMatch(user, candidate);
    if (score > bestScore) {
      bestScore = score;
      best = candidate;
    }
  }
  if (bestScore < MIN_SCORE_VINCULO) return null;
  return best;
}

async function ensureOrigemPontuaGarbo(
  db: ReturnType<typeof dbFromSchema>,
  schema: string | null,
) {
  const originsTable = schema ? "lead_origins" : 'CRM-multi-empresas>lead_origins<';
  const { data: existing } = await db
    .from(originsTable)
    .select("id")
    .ilike("nome", "Pontua Garbo")
    .limit(1)
    .maybeSingle();
  if (existing?.id) return;
  await db.from(originsTable).insert({ nome: PONTUA_GARBO_LEAD_ORIGEM, is_default: false });
}

async function linkLeadToUsuario(
  db: ReturnType<typeof dbFromSchema>,
  leadsTable: string,
  leadId: number,
  usuarioId: string,
): Promise<void> {
  const { data: current } = await db
    .from(leadsTable)
    .select("id")
    .eq("pontua_garbo_usuario_id", usuarioId)
    .maybeSingle();
  if (current?.id && current.id !== leadId) {
    const { error: unlinkErr } = await db
      .from(leadsTable)
      .update({ pontua_garbo_usuario_id: null, atualizado_em: new Date().toISOString() })
      .eq("id", current.id);
    if (unlinkErr) throw unlinkErr;
  }
  const { error } = await db
    .from(leadsTable)
    .update({
      pontua_garbo_usuario_id: usuarioId,
      atualizado_em: new Date().toISOString(),
    })
    .eq("id", leadId);
  if (error) throw error;
}

/**
 * Garante um card de lead para o parceiro Pontua Garbo.
 * Reusa o card da pessoa (pelo nome), não um cliente que só compartilhou o telefone.
 */
export async function ensurePontuaGarboPartnerLead(
  admin: SupabaseClient,
  target: EmpresaDbTarget,
  input: {
    usuarioId: string;
    nome: string;
    email?: string | null;
    telefone?: string | null;
    existingLeadId?: number | null;
  },
): Promise<{ leadId: number | null; created: boolean }> {
  const db = dbFromSchema(admin, target.schema);
  const email = input.email?.trim().toLowerCase() || null;
  const telefone = digitsOnly(input.telefone) || null;
  const userRef = {
    usuarioId: input.usuarioId,
    nome: input.nome,
    email,
    telefone,
  };

  try {
    await ensureOrigemPontuaGarbo(db, target.schema);
  } catch (err) {
    console.warn("ensurePontuaGarboPartnerLead: origem", err);
  }

  if (input.existingLeadId) {
    await linkLeadToUsuario(db, target.leadsTable, input.existingLeadId, input.usuarioId);
    return { leadId: input.existingLeadId, created: false };
  }

  const { data: alreadyLinked, error: linkedErr } = await db
    .from(target.leadsTable)
    .select("id, nome, email, telefone, status, pontua_garbo_usuario_id")
    .eq("pontua_garbo_usuario_id", input.usuarioId)
    .maybeSingle();
  if (linkedErr) throw linkedErr;

  const rawFirst = (input.nome.trim().split(/\s+/)[0] ?? "").replace(/[%_,]/g, " ").trim();
  const firstToken = (partnerNameTokens(input.nome)[0] ?? rawFirst).replace(/[%_,]/g, " ").trim();
  const filters: string[] = [];
  if (email) filters.push(`email.ilike.${email}`);
  if (rawFirst.length >= 3) filters.push(`nome.ilike.%${rawFirst}%`);
  if (firstToken.length >= 3 && firstToken.toLowerCase() !== rawFirst.toLowerCase()) {
    filters.push(`nome.ilike.%${firstToken}%`);
  }

  let candidates: PartnerLeadRow[] = [];
  if (filters.length > 0) {
    const { data: nameRows } = await db
      .from(target.leadsTable)
      .select("id, nome, email, telefone, status, pontua_garbo_usuario_id")
      .or(filters.join(","))
      .order("id", { ascending: true })
      .limit(80);
    candidates = (nameRows ?? []) as PartnerLeadRow[];
  }

  const best = pickBestPartnerLead(userRef, candidates);
  const bestScore = best ? scorePartnerLeadMatch(userRef, best) : 0;
  const linkedScore = alreadyLinked
    ? scorePartnerLeadMatch(userRef, alreadyLinked as PartnerLeadRow)
    : 0;
  const shouldRelink =
    Boolean(best) &&
    bestScore >= MIN_SCORE_VINCULO &&
    (!alreadyLinked || best!.id !== alreadyLinked.id) &&
    (linkedScore < MIN_SCORE_VINCULO || bestScore > linkedScore + 10);

  if (shouldRelink && best) {
    await linkLeadToUsuario(db, target.leadsTable, best.id, input.usuarioId);
    return { leadId: best.id, created: false };
  }
  if (alreadyLinked?.id && linkedScore >= MIN_SCORE_VINCULO) {
    return { leadId: alreadyLinked.id as number, created: false };
  }
  if (best) {
    await linkLeadToUsuario(db, target.leadsTable, best.id, input.usuarioId);
    return { leadId: best.id, created: false };
  }
  if (alreadyLinked?.id) {
    return { leadId: alreadyLinked.id as number, created: false };
  }

  const { data: created, error: insertErr } = await db
    .from(target.leadsTable)
    .insert({
      nome: input.nome.trim(),
      email,
      telefone,
      origem: PONTUA_GARBO_LEAD_ORIGEM,
      status: "Novo Lead",
      valor_negocio: 0,
      valor_orcamento: 0,
      data_chegada: todaySaoPaulo(),
      pontua_garbo_usuario_id: input.usuarioId,
      observacoes: "Cadastro automático pelo programa Pontua Garbo.",
    })
    .select("id")
    .single();

  if (insertErr) throw insertErr;
  return { leadId: (created?.id as number) ?? null, created: true };
}
